import { z } from "zod";
import { CHAT_INBOXES, CHAT_MESSAGE_MAX_LENGTH, CHAT_REPORT_ACTIONS, REPORT_REASONS, REPORT_STATUSES } from "../constants";
import { cursorQuerySchema, isoDateTimeSchema, optionalTrimmed, pageQuerySchema, uuidSchema } from "./common";

/** Generated by the client for each message, so a retry after a lost response can't send it twice. */
export const chatClientKeySchema = z.string().regex(/^[A-Za-z0-9_-]{8,64}$/, "Use 8 to 64 letters, digits, hyphens or underscores");

// A NUL would otherwise reach Postgres and fail the send. Newlines and tabs are kept.
// eslint-disable-next-line no-control-regex -- matching control characters is the point
const CONTROL_CHARACTERS = /[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g;

/** Zero-width and other invisible characters count as nothing, or a message could be an empty bubble. */
const VISIBLE_CHARACTER = /[^\s\u00AD\u200B-\u200F\u2028-\u202F\u2060-\u206F\uFEFF]/;

export const chatMessageBodySchema = z
  .string()
  .transform((v) => v.replace(CONTROL_CHARACTERS, "").trim())
  .pipe(z.string().min(1, "Write a message").max(CHAT_MESSAGE_MAX_LENGTH).regex(VISIBLE_CHARACTER, "Write a message"));

export const chatMessageCreateSchema = z.object({ body: chatMessageBodySchema, clientKey: chatClientKeySchema });
export type ChatMessageCreateInput = z.input<typeof chatMessageCreateSchema>;

export const chatDirectCreateSchema = chatMessageCreateSchema.extend({ membershipId: uuidSchema });
export type ChatDirectCreateInput = z.input<typeof chatDirectCreateSchema>;

export const chatConversationsQuerySchema = cursorQuerySchema.extend({ inbox: z.enum(CHAT_INBOXES).default("MAIN") });
export type ChatConversationsQuery = z.infer<typeof chatConversationsQuerySchema>;

/** `cursor` pages back through older messages, newest first. `afterSeq` fetches what came after, oldest first. */
export const chatMessagesQuerySchema = cursorQuerySchema
  .extend({ afterSeq: z.string().max(20).optional() })
  .refine((q) => !(q.cursor && q.afterSeq !== undefined), "Use cursor or afterSeq, not both");
export type ChatMessagesQuery = z.infer<typeof chatMessagesQuerySchema>;

export const chatReadSchema = z.object({ seq: z.number().int().min(0).max(2147483647) });
export type ChatReadInput = z.infer<typeof chatReadSchema>;

/** `until: null` unmutes. */
export const chatMuteSchema = z.object({ until: isoDateTimeSchema.nullable() });
export type ChatMuteInput = z.infer<typeof chatMuteSchema>;

export const chatBlockCreateSchema = z.object({ membershipId: uuidSchema });
export type ChatBlockCreateInput = z.infer<typeof chatBlockCreateSchema>;

export const chatReportCreateSchema = z.object({ reason: z.enum(REPORT_REASONS), details: optionalTrimmed(1000) });
export type ChatReportCreateInput = z.input<typeof chatReportCreateSchema>;

export const adminChatReportsQuerySchema = pageQuerySchema.extend({ status: z.enum(REPORT_STATUSES).default("OPEN") });
export type AdminChatReportsQuery = z.infer<typeof adminChatReportsQuerySchema>;

export const chatReportResolveSchema = z.object({ action: z.enum(CHAT_REPORT_ACTIONS), note: optionalTrimmed(500) });
export type ChatReportResolveInput = z.infer<typeof chatReportResolveSchema>;
